select count(*) > 0
from consumer_staff_call_setting
where sys_plant_cd = #{sysPlantCd}
  and call_cd = #{callCd}

  and sys_id != #{excludeSysId}

select count(*) > 0
from consumer_staff_call_setting
where sys_plant_cd = #{sysPlantCd} and sys_id = #{sysId}

mapper.update:
update consumer_staff_call_setting
set call_cd = #{item.callCd}, call_nm = #{item.callNm},
    single_yn = #{item.singleYn}, description = #{item.description}
where sys_id = #{item.sysId} and sys_plant_cd = #{sysPlantCd}
